'use strict';
// Copies the static web app (public/) into a native bundle directory.
// Only public/ is read: server.js, backend/, scripts/, tests and databases are never copied.
const fs = require('node:fs');
const path = require('node:path');
const { validateServerUrl } = require('./server-url');

// Files that only make sense on the web server: the native shell has no service worker.
const SKIP = new Set(['sw.js', 'v9/sw.js']);
const BLOCKED = /\.(sqlite|sqlite3|db|env|pem|key)(-.*)?$|(^|\/)\.env/i;

function listFiles(dir, base = dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap(entry => {
    const full = path.join(dir, entry.name);
    if (entry.name.startsWith('.')) return [];
    if (entry.isSymbolicLink()) return [];
    return entry.isDirectory() ? listFiles(full, base) : [path.relative(base, full).split(path.sep).join('/')];
  });
}

function runtimeConfig(apiBase) {
  return `// Generated by mobile/scripts/bundle-web.js for the native app. Do not edit.\nwindow.FORMCLUB_CONFIG = Object.freeze(${JSON.stringify({ apiBase, native: true })});\n`;
}

function bundleWeb({ publicDir, outDir, apiUrl, allowCleartext = false }) {
  const api = validateServerUrl(apiUrl, { allowCleartext });
  const source = fs.realpathSync(publicDir);
  const requested=path.resolve(outDir);
  if(fs.existsSync(requested)&&fs.lstatSync(requested).isSymbolicLink())throw Error('Bundle output cannot be a symlink');
  let parent=requested;const tail=[];
  while(!fs.existsSync(parent)){tail.unshift(path.basename(parent));parent=path.dirname(parent)}
  const output=path.join(fs.realpathSync(parent),...tail);
  if(output===source||source.startsWith(output+path.sep)||output.startsWith(source+path.sep))throw Error('Bundle output must be separate from source');
  if(fs.existsSync(output)&&fs.lstatSync(output).isSymbolicLink())throw Error('Bundle output cannot be a symlink');
  const files=listFiles(source).filter(rel=>!SKIP.has(rel));
  for(const rel of files)if(BLOCKED.test(rel))throw Error('public/ içinde paketlenmemesi gereken dosya var: '+rel);
  fs.rmSync(output, { recursive: true, force: true });
  const copied = [];
  for (const rel of files) {
    if (SKIP.has(rel)) continue;
    if (BLOCKED.test(rel)) throw Error('public/ içinde paketlenmemesi gereken dosya var: ' + rel);
    const target = path.join(outDir, rel);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.copyFileSync(path.join(source, rel), target);
    copied.push(rel);
  }
  if (!copied.includes('index.html') || !copied.includes('runtime-config.js')) throw Error('public/index.html veya public/runtime-config.js bulunamadı');
  fs.writeFileSync(path.join(outDir, 'runtime-config.js'), runtimeConfig(api.origin));
  return { files: copied.length, apiBase: api.origin };
}

module.exports = { bundleWeb, runtimeConfig, listFiles };
